  Stage_122601_Name = {
    Text = "Prova di Mouchette"
  },
  Stage_123112_Desc = {
    Text = "Le nebbie hanno velato i miei occhi, recidendo il legame con il mio stesso mondo. Eppure, attraverso i tuoi occhi, scorgo il passato a cui non potrò mai fare Ritorno e le persone che non incontrerò mai più. Siamo Consanguinei."
  },
  Stage_123112_Name = {
    Text = "Attraverso il Tuo Sguardo"
  },
  Stage_123113_Desc = {
    Text = "Le nebbie hanno velato i miei occhi, recidendo il legame con il mio stesso mondo. Eppure, attraverso i tuoi occhi, scorgo il passato a cui non potrò mai fare Ritorno e le persone che non incontrerò mai più. Siamo Consanguinei."
  },
  Stage_123113_Name = {
    Text = "Attraverso il Tuo Sguardo"
  },
  Stage_125199_Desc = {
    Text = "Solo l'insetto assuefatto d'amore è così fragile, così tenace, così ridicolo, eppure così straordinario.\nAh, vieni con me a vedere qualcosa di ancor più meraviglioso. Vi prenderete cura l'uno dell'altro, e sarete legati indissolubilmente da ora in poi."
  },
  Stage_125199_Name = {
    Text = "Laccio di seta: III"
  },
  Stage_125200_Desc = {
    Text = "L'amore appassionato trova sempre la sua fine, sebbene non sempre nell'invecchiare insieme; più spesso, si conclude in una morte prematura.\nTalvolta è l'amore a perire invano, e talvolta sei tu."
  },
  Stage_125200_Name = {
    Text = "Morte ingiusta: Follia"
  },
  Stage_125201_Desc = {
    Text = "Il tuo vecchio amante è ormai defunto da tempo; perché solo adesso inizi a provare rimpianto?\nHiihii... non temere; non è troppo tardi. Guarda, mia cara. Finché il sole tramonta, ogni lampada, ogni candela rossa, proietterà la sua forma e la sua ombra su ogni finestra di carta."
  },
  Stage_125201_Name = {
    Text = "Ombra alle spalle: II"
  },
  Stage_125202_Desc = {
    Text = "\"...Come una cicala che si libera del suo guscio e rinnova le sue ossa, questo è chiamato \"Ascensione del Cadavere\"—ascendere all'immortalità attraverso la dissoluzione corporea...\"\nOh, ma in realtà—non è affatto vero. È solo un ridicolo racconto antico. Ma che importa? Pregarono con sangue e lacrime, e da queste preghiere, una bellezza—o un puro terrore—rinacque."
  },
  Stage_125202_Name = {
    Text = "Ascensione del cadavere: VI"
  },
  Stage_125203_Desc = {
    Text = "Il tuo vecchio amante è ormai defunto da tempo; perché solo adesso inizi a provare rimpianto?\nHiihii... non temere; non è troppo tardi. Guarda, mia cara. Finché il sole tramonta, ogni lampada, ogni candela rossa, proietterà la sua forma e la sua ombra su ogni finestra di carta."
  },
  Stage_125203_Name = {
    Text = "Ombra alle spalle: I"
  },
  Stage_125204_Desc = {
    Text = "Si inginocchiano insieme dinanzi all'altare delle offerte. La Matriarca d'Ossidiana è impercettibile, indefinibile e irresistibile.\nOffri tutto, obbedisci a tutto; ascendi alla beatitudine suprema, all'eterno caos."
  },
  Stage_125204_Name = {
    Text = "Euforia: Follia"
  },
  Stage_125205_Desc = {
    Text = "Mi piace il tuo profumo, e assaggerò i tuoi nemici per te."
  },
  Stage_125205_Name = {
    Text = "Seguendo la traccia: II"
  },
  Stage_125206_Desc = {
    Text = "Quella setta misteriosa vaga al di fuori delle cronache storiche dell'antica nazione orientale; non può essere scoperta né definita. Solo pochissimi individui, che non sono ancora periti e dimorano per sempre nella Terra senza sogni, hanno mai appreso il vero nome della divinità che essa venera.\nIl suo nome è—\"@4\""
  },
  Stage_125206_Name = {
    Text = "Grazia crescente: I"
  },
  Stage_125207_Desc = {
    Text = "Si inginocchiano insieme dinanzi all'altare delle offerte. La Matriarca d'Ossidiana è impercettibile, indefinibile e irresistibile.\nOffri tutto, obbedisci a tutto; ascendi alla beatitudine suprema, all'eterno caos."
  },
  Stage_125207_Name = {
    Text = "Euforia: VI"
  },
  Stage_125208_Desc = {
    Text = "Crack—slurp—gorgoglio—mmph—\nStaremo insieme per sempre, staremo insieme per sempre.\nStaremo insieme per semPREPERsemprePERSEMpre-semPRE SEMPRE@4"
  },
