  Stage_125648_Name = {
    Text = "Il Verdetto"
  },
  Stage_125649_Desc = {
    Text = "Un uragano dall'altra parte dell'oceano non è mai dipeso dalla scelta della farfalla."
  },
  Stage_125649_Name = {Text = "Spari"},
  Stage_125650_Desc = {
