  Stage_125652_Name = {
    Text = "Vola, Cigno, Vola"
  },
  Stage_125653_Desc = {
    Text = "90 minuti di mezzanotte, una maschera da 15 pollici, 10 galloni di sogni e 2 once di alcol: l'unica ricetta per la Gioia."
  },
  Stage_125653_Name = {Text = "Mascherata"},
  Stage_125654_Desc = {
    Text = "Uno spettacolo nuovo meticolosamente provato: visione gratuita, uscita vietata."
  },
  Stage_125654_Name = {
    Text = "L'Attore Interiore"
  },
  Stage_125655_Desc = {
    Text = "Ridi e canta! Amico mio! Sul palcoscenico del destino, il piacere è l'unico protagonista."
  },
  Stage_125655_Name = {
    Text = "Commedia Improvvisata"
  },
  Stage_125656_Desc = {
    Text = "I nostri ruoli sono già assegnati prima di entrare in teatro."
