  Stage_125662_Name = {Text = "Spari"},
  Stage_125663_Desc = {
    Text = "La gabbia immortale è intessuta dalle mani stesse dei prigionieri.\nTessono per l'eternità. Non sono mai fuggiti."
  },
  Stage_125663_Name = {Text = "Bozzolo"},
  Stage_126202_Desc = {
    Text = "Fiori, ovazioni, applausi. Il mondo converge su di esso ancora una volta.\nIl mago della narrazione ha concluso lo spettacolo; i ricordi degli spettatori si dissolvono in un elegante inchino.\nNessun segreto, per quanto oscuro, sfuggirà mai dalle rovine del palcoscenico."
  },
  Stage_126202_Name = {
    Text = "Niente Spoiler: IV"
  },
  Stage_126203_Desc = {
    Text = "Ecco—il crescendo del racconto! Ogni presagio non è che combustibile; ogni preparazione, una scintilla per incendiare il palcoscenico in questo momento culminante."
  },
  Stage_126203_Name = {
    Text = "Combustione: IV"
  },
  Stage_126204_Desc = {
