  Stage_24183_Name = {
    Text = "Prova della Dama in Rosso"
  },
  Stage_24184_Name = {
    Text = "Prova del Fiore di Melma"
  },
  Stage_24423_Desc = {
    Text = "Nessun cittadino di Londinium rifiuterebbe una tazza di tè appena preparata.\nNemmeno un oolong alla lampreda."
  },
  Stage_24423_Name = {
    Text = "Elisir di Lampreda"
  },
  Stage_24424_Desc = {
    Text = "Tutti coloro che il fato ha scelto si credono l'eccezione.\nIl fato si fa beffe della probabilità."
  },
  Stage_24424_Name = {
    Text = "Prigioniero del Destino"
  },
  Stage_24425_Desc = {
    Text = "Snip.\nGiurò di recidere ogni legame con la sua vita passata.\nCome tagliare un nastro nettamente in due."
  },
  Stage_24425_Name = {Text = "Per Sorel"},
  Stage_24426_Desc = {
    Text = "Ancora una volta, la compassione ti cattura, trascinandoti a capofitto nella sua anima."
  },
  Stage_24426_Name = {
    Text = "Verdetto Caduto"
  },
  Stage_24427_Desc = {
    Text = "All'alba della storia, assisti a una morte magnifica.\nÈ l'inizio, ma è ben lungi dall'essere la fine."
  },
  Stage_24427_Name = {
    Text = "Canzone del Bere"
  },
  Stage_24428_Desc = {
    Text = "Il nome della ragazza è Sorel; è l'orgoglio del villaggio.\nObbediente e immacolata, vestita di bianco, si muove a piccoli passi come una vera signora.\nEppure, a differenza di quelle signore, lei non sogna mai."
  },
  Stage_24429_Desc = {
    Text = "La logica è come il whiskey: troppa perde il suo beneficio."
  },
  Stage_24429_Name = {
    Text = "Armonia Mascherata"
  },
  Stage_24430_Desc = {
    Text = "Sotto la Sua meticolosa coltivazione, il cancro dell'ambizione infine si propagò come rose in fiore."
  },
  Stage_24430_Name = {
    Text = "Festa cremisi e oro"
  },
  Stage_24431_Desc = {
    Text = "Slurp. Slurp.\nCi contorciamo nelle ombre, mormoriamo tra noi.\nCorpi carnosi trascinano sinuose traiettorie di lacrime sotto il chiaro di luna — salate, per giunta."
  },
  Stage_24431_Name = {Text = "Uovo"},
  Stage_24432_Desc = {
    Text = "Focaccine, macaron e cioccolata fumante...\nIl desiderio dell'ancella è semplice: mangiare un po' meglio. E poi un po' meglio ancora."
  },
  Stage_24432_Name = {
    Text = "Desiderio dell'ancella"
  },
  Stage_24433_Desc = {
    Text = "Attenti, attenti.\nLa signora che tutti ammirate non è una vera signora.\nMa a chi importa?"
  },
  Stage_24433_Name = {
    Text = "Guida della Dama"
  },
  Stage_24434_Desc = {
    Text = [[
La rosa china il suo esile capo al rintocco della campana; l'avvoltoio si perde tra fiori fetidi.
Nessuno canta. Nessuno parla. Il mondo si prosciuga di colore con la sua morte.]]
  },
  Stage_24434_Name = {
    Text = "Rosafunebre"
  },
  Stage_24435_Desc = {
    Text = "Lei prosciuga le sorgenti fino all'ultima goccia, strangolando uccelli innocenti.\nPorta venti dorati che spazzano i campi come meteore.\nDà alle fiamme il mondo col desiderio, poi lo riduce in ceneri."
  },
  Stage_24435_Name = {
    Text = "Dama delle Camelie"
  },
