  Stage_24528_Desc = {
    Text = "Non importa cosa accada, non importa quanto venga trasformato: il tuo richiamo sarà sempre udito."
  },
  Stage_24528_Name = {
    Text = "Non è un addio"
  },
  Stage_24529_Desc = {
    Text = "Una, due, tre volte — Sisifo spinge il suo macigno, ascendendo invano verso una vetta che non può essere raggiunta."
  },
  Stage_24529_Name = {Text = "Sisifo"},
  Stage_24530_Desc = {
    Text = "La ragazza un tempo familiare è diventata un'estranea. Questa figura fredda e distante — può davvero essere la Ramona che conoscevi?"
  },
  Stage_24530_Name = {
    Text = "Tutto per tutto"
  },
  Stage_24531_Desc = {
    Text = "Un giorno ordinario inizia con un sogno straordinario."
  },
  Stage_24531_Name = {
    Text = "Lacrime di pioggia"
  },
  Stage_24532_Desc = {
    Text = "La ragazza un tempo familiare è diventata un'estranea. Questa figura fredda e distante — può davvero essere la Ramona che conoscevi?"
  },
  Stage_24532_Name = {
    Text = "Tutto per tutto"
  },
  Stage_24533_Desc = {
    Text = "La ragazza un tempo familiare è diventata un'estranea. Questa figura fredda e distante — può davvero essere la Ramona che conoscevi?"
  },
  Stage_24533_Name = {
    Text = "Tutto per tutto"
  },
  Stage_34716_Desc = {
    Text = "Un colpo di scena improvviso, una svolta inattesa, un mutamento nella storia — il Custode non può fare a meno di sentire che questo, a volte, descrive sé stesso."
  },
  Stage_34716_Name = {
    Text = "III: Rotazione della Trama"
  },
  Stage_34717_Desc = {
    Text = "Questa è una parola che neppure Ramona aveva mai udito. Con l'aiuto di alcuni anziani Risvegliati, tutti infine compresero: a volte, un bel pianto è l'unico rimedio per uno spirito turbato."
  },
  Stage_34717_Name = {
    Text = "II: Catarsi"
  },
  Stage_34718_Desc = {
    Text = "Il libro di teoria trovato da Casiah afferma: il tempo della storia non può superare un giorno, e il livello non può superare un'unica ambientazione...\nIl Custode ha rinunciato a leggerlo. Dopotutto, a volte nemmeno un giorno basta per completare un elaborato post-lezione su \"Dissoluzione e Prevenzione del Cataclisma\"."
  },
  Stage_34718_Name = {
    Text = "I: Unità Classiche"
  },
  Stage_34719_Desc = {
    Text = "Il volume teorico trovato da Casiah recita: il modello piramidale si occupa della risoluzione di una crisi.\nEppure non ogni crisi trova risoluzione nella realtà. Vengono occultate sotto l'illusione della pace, marcendo nell'oscurità, finché non erompono in una nuova \"piramide.\""
  },
  Stage_34719_Name = {
    Text = "VII: Apice del Dramma"
  },
  Stage_34720_Desc = {
    Text = "Alla fine di una storia, un personaggio deve mostrare crescita o trasformazione. Eppure nella vita, l'arco narrativo ha il vizio di ripiegarsi in un cerchio."
  },
  Stage_34720_Name = {
    Text = "VI: Teorema dell'Arco"
  },
  Stage_34721_Desc = {
    Text = "Una scena preparata in anticipo, un pugno di attori familiari. Il resto è affidato all'ispirazione e all'interazione."
  },
  Stage_34721_Name = {
    Text = "V: Farsa Mascherata"
  },
  Stage_34722_Desc = {
    Text = "Non bombardare la mente del pubblico a ogni istante; lascia loro spazio per pensare — idealmente, lasciali in completa immobilità. Se solo Doll potesse applicare questo principio durante le lezioni, mormorò il Custode, e tutti annuirono."
  },
  Stage_34722_Name = {
    Text = "IV: Istante di Quiete"
  },
  Stage_34912_Desc = {
    Text = "L'antica Calamità ora si desta — oltrepassando il confine verso il mondo presente, incendia il mare sconfinato di corruzione."
  },
  Stage_34912_Name = {
    Text = "Zona D-Effetto: Ondata 1: Allerta III"
  },
