  Stage_35099_Desc = {
    Text = "\"Shh — indovina cosa ho visto attraverso i tuoi occhi?\"\nDopo che il Custode fece piangere Aurita dallo spavento, Lotan quasi abbatté la Quarta Parete della stanza del Custode, perché il pianto di Aurita era semplicemente troppo inquietante."
  },
  Stage_35099_Name = {
    Text = "IX: La Quarta Parete"
  },
  Stage_35100_Desc = {
    Text = "\"Non lasciare che il pubblico si perda interamente nella storia; costringilo ad analizzare e criticare ciò che si svolge sul palco.\"\nSu questa teoria, Aurita ebbe da dire quanto segue: Aurita non vuole essere sgridata da nessuno! Aurita vuole solo essere amica di tutti!"
  },
  Stage_35100_Name = {
    Text = "VIII: Effetto di Straniamento"
  },
  Stage_35129_Desc = {
    Text = "Lei è il confine dove sogno e realtà si intrecciano — il riflesso che dimora nelle profondità di ogni anima che volge lo sguardo al cielo notturno."
  },
  Stage_35129_Name = {
    Text = "Stelle distorte"
  },
  Stage_35129_StageInitStateText = {
    Text = "Incubo marino"
  },
  Stage_35130_Desc = {Text = "È pronta."},
  Stage_35130_Name = {
    Text = "Fiamma Interiorizzata"
  },
  Stage_35571_Desc = {
    Text = "Poiché sei amico di Aurita, vuole presentarti tutti i suoi amici."
  },
  Stage_35571_Name = {
    Text = "Compendio degli amici"
  },
  Stage_35572_Desc = {
    Text = "Poiché sei amico di Aurita, vuole presentarti tutti i suoi amici."
  },
  Stage_35572_Name = {
    Text = "Compendio degli amici"
  },
  Stage_35573_Desc = {
    Text = "Poiché sei amico di Aurita, vuole presentarti tutti i suoi amici."
  },
  Stage_35573_Name = {
    Text = "Compendio degli amici"
  },
  Stage_35574_Desc = {
    Text = "Ad Aurita piaci, e desidera che tu diventi un amico con cui condividere le sue giornate ordinarie."
  },
  Stage_35574_Name = {
    Text = "Giorno Silente"
  },
  Stage_35575_Desc = {
    Text = "Con Tutti al suo fianco, Aurita non ha Terrore di addormentarsi."
  },
  Stage_35575_Name = {
    Text = "Palazzo Sottomarino"
  },
  Stage_35843_Name = {
    Text = "Prova della Dama delle Profondità"
  },
  Stage_35857_Desc = {
    Text = "Le stelle sono andate dove appartengono, comunicando in modi che trascendono la comprensione umana; tessendo una tela invisibile che cattura il fluire del tempo e la luce degli anni trascorsi."
  },
  Stage_35857_Name = {
    Text = "Sentiero Astrale Sconosciuto"
  },
