  Stage_36614_Desc = {
    Text = "Crogiolarsi nella lussuria, arrendersi al desiderio...\n—E poi?\nAffrontare fiamme eterne come monito per tutti.\n—Oh."
  },
  Stage_36614_Name = {
    Text = "Notte di Morte, Idromele e Canto"
  },
  Stage_36615_Desc = {
    Text = "Quattro matrimoni e quattro funerali: l'unica nota a piè di pagina della \"vita sentimentale\" di Wanda nel mondo mortale."
  },
