  Stage_38769_Name = {
    Text = "Miraggio: Rimembranza Parte IV"
  },
  Stage_38770_Desc = {
    Text = "Di notte, la Regina si trovava sulla terrazza del palazzo, contemplando la città migliaia di piedi più in basso.\nGiorno dopo giorno, ogni volta che cercava di varcare i confini del palazzo, vertigini, lacrime e vasti vuoti di memoria la assalivano.\n\"Sei pronta? Ad affrontare la verità di questo mondo.\"\nTrasse un respiro profondo e si lanciò dalla terrazza."
  },
  Stage_38770_Name = {
    Text = "Verità Nascosta: Rimembranza: Parte I"
  },
  Stage_38771_Desc = {
    Text = "Di notte, la Regina si trovava sulla terrazza del palazzo, contemplando la città migliaia di piedi più in basso.\nGiorno dopo giorno, ogni volta che cercava di varcare i confini del palazzo, vertigini, lacrime e vasti vuoti di memoria la assalivano.\n\"Sei pronta? Ad affrontare la verità di questo mondo.\"\nTrasse un respiro profondo e si lanciò dalla terrazza."
  },
  Stage_38771_Name = {
    Text = "Verità Nascosta: Rimembranza Parte III"
  },
  Stage_38772_Desc = {
    Text = "Quando aprì gli occhi, il mondo si stava disfacendo.\nOgni edificio era crollato; una melma nera lambiva il cielo; fresie bianche si dissolvevano nel vuoto eterno.\nTutto era silenzio. Tutto sembrava addormentato.\nSolo le sue lacrime erano fredde, appiccicate al viso, a inzupparle i capelli."
  },
  Stage_38772_Name = {
    Text = "Pozzo profondo: Rimembranza Parte IV"
  },
