  Stage_55142_Name = {
    Text = "Ceneri Residue: Follia"
  },
  Stage_55142_StageInitStateText = {
    Text = "Fine Ultima"
  },
  Stage_55143_Desc = {
    Text = "La piccola casa dei fiori è il loro piccolo regno.\nIn questo modesto reame non possiedono nulla — e non vorrebbero che fosse altrimenti."
  },
  Stage_55143_Name = {
    Text = "Regno Minuscolo: Parte IV"
  },
  Stage_55144_Desc = {
    Text = "Il celebre componimento portò ogni cosa; lei arrossì alle lodi dell'amica. I suoi versi avevano finalmente risparmiato all'amica la sofferenza — o almeno così credeva.\nCiò che non udì fu che i semi della malvagità erano già stati piantati, in agguato, pronti a intrecciare le rose e distruggerle."
  },
