  Stage_56907_Name = {
    Text = "Ballo di Carnevale: Parte VI"
  },
  Stage_56908_Desc = {
    Text = "Una sinfonia non è un'impresa solitaria.\nArchi, legni, ottoni, percussioni.\nOgni sezione strumentale, nel suo ordine, china il capo in attesa della sua direzione."
  },
  Stage_56908_Name = {
    Text = "Grande Orchestrazione: Parte V"
  },
  Stage_56909_Desc = {
    Text = "Sboccia come fuochi d'artificio, anche se la vita stessa è il combustibile.\nQuando tutte le destinazioni convergono, perché sopportare sofferenze infinite invece di abbracciare uno splendore radioso?"
  },
  Stage_56909_Name = {
    Text = "Caduta radiosa: Parte II"
  },
  Stage_56910_Desc = {
    Text = "Innumerevoli anime bramano la verità, avanzando a ondate. Innumerevoli stolti stringono frammenti di realtà, scambiando cieche epifanie per luce divina, predicando splendori celesti."
  },
  Stage_56910_Name = {
    Text = "Veleno Autentico: Parte V"
  },
  Stage_56911_Desc = {
    Text = "Lei tende la mano — vuoi danzare?\nAvanti, indietro, i tuoi passi rispecchiano solo i suoi.\nStringi il suo palmo, segui il suo ritmo, non chinare mai il capo.\nAnche mentre l'abisso spalanca le fauci sotto i tuoi piedi."
  },
