  Stage_58089_Desc = {
    Text = "La loro paura della peste si tramutò in rabbia.\n\"Dammi il tuo sangue — dammi tutto!\"\n\"Come osi restare a guardare senza far nulla? Come osi fermarti qui?!\""
  },
