  Stage_58385_Name = {
    Text = "Miraggio: Follia"
  },
  Stage_58385_StageInitStateText = {
    Text = "Fine Ultima"
  },
  Stage_58386_Desc = {
    Text = "Chiude gli occhi e fluttua senza meta nel vuoto dell'universo.\nUn anno, cento anni... Infine, un giorno, dice a sé stessa: \"Va bene così. Sarò io a definire il vero e il falso.\"\nLa Regina e la sua città immortale — Isarawu, restano così sospese nell'immensa galassia dell'universo.\nCondivide con me la storia di Isarawu, affinché sia ricordata in eterno."
  },
