  Stage_59503_Name = {Text = "Rito"},
  Stage_59503_StageInitStateText = {Text = "Origine"},
  Stage_59504_Desc = {
    Text = "In piedi nel tempio del sogno, a sorreggere le rovine che crollano.\nA custodire il granello di polvere sotto di te — quello che porta con sé tutta la tua devozione e nostalgia."
  },
  Stage_59504_Name = {
