  Stage_62348_Desc = {
    Text = "Questo è il crescendo delle stelle. Questo è il cala il sipario del cosmo.\nIn questo silenzio profondo, ascolta con attenzione—\nriesci a udire le note autentiche?"
  },
  Stage_62348_Name = {
    Text = "Fine Ultima"
  },
  Stage_66016_Desc = {
    Text = "È la Volontà suprema, il Creatore dell'universo e Colui che pone fine a ogni cosa.\nLamentatevi al Suo cospetto. Per il vostro fragile coraggio, per le Sue sconfinate Autorità."
  },
  Stage_66016_Name = {
    Text = "Ospizio dei Poveri: Visione del Lamento"
  },
  Stage_66016_StageInitStateText = {Text = "Origine"},
  Stage_66017_Desc = {
    Text = "È la Volontà suprema, il Creatore dell'universo e Colui che pone fine a ogni cosa.\nLamentatevi al Suo cospetto. Per il vostro fragile coraggio, per le Sue sconfinate Autorità."
  },
  Stage_66017_Name = {
    Text = "Ospizio dei Poveri: Visione del Lamento"
  },
  Stage_66017_StageInitStateText = {Text = "Origine"},
  Stage_66018_Desc = {
    Text = "È la Volontà suprema, il Creatore dell'universo e Colui che pone fine a ogni cosa.\nLamentatevi al Suo cospetto. Per il vostro fragile coraggio, per le Sue sconfinate Autorità."
  },
  Stage_66018_Name = {
    Text = "Ospizio dei Poveri: Visione del Lamento"
  },
  Stage_66381_Desc = {
    Text = "Non temete, poiché la paura è l'istinto più primordiale degli esseri viventi.\nIl Divino non turba neppure una singola formica. Vi benedice con il risveglio."
  },
  Stage_66381_Name = {
    Text = "Museo delle Cere:: Visuale della Paura"
  },
  Stage_66381_StageInitStateText = {Text = "Origine"},
  Stage_66382_Desc = {
    Text = [[
Cantate, cantate del nostro grande Creatore!
Quando Esso sogna, i viventi prosperano.
Quando apre i Suoi occhi, ogni cosa si riduce in polvere.]]
  },
  Stage_66382_Name = {
    Text = "Bridgeport: Visione dell'Eresia"
  },
  Stage_66382_StageInitStateText = {Text = "Origine"},
  Stage_66383_Desc = {
    Text = "Senti il dolore; senti il dono più primordiale della Volontà Suprema.\nAttraverso il dolore, potrai intravedere la maestà del Creatore."
  },
  Stage_66383_Name = {
    Text = "Rye: Visione del Gelo"
  },
  Stage_66383_StageInitStateText = {Text = "Origine"},
  Stage_66384_Desc = {
    Text = "Non c'è bisogno di lottare. Non c'è bisogno di resistere. Perché tentare di comprendere l'incomprensibile?\nSotto lo Sguardo della Volontà Suprema, abbracciamo la fine del sogno."
  },
  Stage_66384_Name = {
    Text = "Sanatorio: Visione dell'Enigma"
  },
  Stage_66384_StageInitStateText = {Text = "Origine"},
  Stage_66385_Desc = {
    Text = "È la Volontà suprema, il Creatore dell'universo e Colui che pone fine a ogni cosa.\nLamentatevi al Suo cospetto. Per il vostro fragile coraggio, per le Sue sconfinate Autorità."
  },
  Stage_66385_Name = {
    Text = "Ospizio dei Poveri: Visione del Lamento"
  },
  Stage_66385_StageInitStateText = {Text = "Origine"},
  Stage_67123_Desc = {
    Text = "Quella magnifica civiltà, quelle gioie e quei dolori del mondo umano, le innumerevoli persone intorno a te che sono venute e andate — non sono mai esistite. La Dissoluzione dei sogni giungerà infine.\nDimentica, Custode. L'Oblio è la più grande delle sofferenze.\nL'Oblio è il rimedio della beatitudine suprema."
  },
  Stage_67123_Name = {
    Text = "Remouahe: Visuale della Nascita"
  },
  Stage_67123_StageInitStateText = {Text = "Origine"},
  Stage_67124_Desc = {
