  Stage_7944_Name = {
    Text = "Immersione Fantasmatica II"
  },
  Stage_7945_Desc = {
    Text = "Lei è il confine dove sogno e realtà si intrecciano — il riflesso che dimora nelle profondità di ogni anima che volge lo sguardo al cielo notturno."
  },
  Stage_7945_Name = {
    Text = "Stelle distorte"
  },
  Stage_7945_StageInitStateText = {
    Text = "Incubo marino"
  },
  Stage_7946_Desc = {
    Text = "L'orizzonte curvo celato nelle profondità del cosmo.\nTi conduce da un'oscurità a un'altra."
  },
  Stage_7946_Name = {
    Text = "Gola di Schwarzschild I"
  },
  Stage_7947_Desc = {
    Text = "Il \"Cancello\" sta per aprirsi, rivelando uno scorcio della verità.\nNon è né bianco né nero — la verità è cromatica eppure torbida."
  },
  Stage_7947_Name = {
    Text = "Dominio del Caos: Fessura III"
  },
  Stage_7948_Desc = {
    Text = "Qui giacciono le rovine di un'antica città nel dormiveglia.\nDorme profondamente quanto il suo padrone."
  },
  Stage_7948_Name = {
    Text = "Rovine di Pohnpei V"
  },
  Stage_7949_Desc = {
    Text = "Riposa docile contro il capezzale, i suoi opachi occhi di bottone fissi nel vuoto.\nIl piccolo corpo ha sopportato tutte le lacrime della sua padrona, eppure non può offrire una sola parola di conforto."
  },
  Stage_7949_Name = {
    Text = "Lacrime della Bambola II"
  },
  Stage_7950_Desc = {
    Text = "Per la vostra salute e la vostra vita, tenetevi lontani dalla nicotina."
  },
  Stage_7950_Name = {
    Text = "Fumo e Violetta"
  },
  Stage_7951_Desc = {
    Text = "Idoli di origine ignota vagano e fremono nell'oscurità.\nSi muovono seguendo ritmi ancestrali, attratti dal suono di un flauto lontano."
  },
  Stage_7951_Name = {
    Text = "Palude di Caro: Fessura II"
  },
  Stage_7952_Desc = {
    Text = "Offri la realtà forgiata da carne e sangue — sono un abisso insaziabile."
  },
  Stage_7952_Name = {
    Text = "Residuo Organico III"
  },
  Stage_7953_Desc = {
    Text = "L'idolo in rovina contempla il suo popolo;\nLo osserva sopravvivere, moltiplicarsi, combattere — e col tempo, dimenticarlo del tutto.\nL'idolo in rovina anela al suo popolo..."
  },
  Stage_7953_Name = {
    Text = "Immersione Fantasmatica II"
  },
  Stage_7954_Desc = {
    Text = "Poi svanì, divorata dall'oscurità.\nLa gente alzò lo sguardo, occhi spalancati, contemplando il cielo che lei aveva attraversato."
  },
  Stage_7954_Name = {
    Text = "Legno di Cedro"
  },
  Stage_7955_Desc = {
    Text = "Sull'altare della sua bellezza, offro le mie lacrime, i miei sospiri e il mio cuore sincero."
  },
  Stage_7955_Name = {Text = "Galatea"},
  Stage_7956_Desc = {
    Text = "L'idolo in rovina contempla il suo popolo;\nLo osserva sopravvivere, moltiplicarsi, combattere — e col tempo, dimenticarlo del tutto.\nL'idolo in rovina anela al suo popolo..."
  },
  Stage_7956_Name = {
    Text = "Immersione Fantasmatica V"
  },
  Stage_79574_Desc = {
    Text = "Un cuore esposto, un antico esemplare, una fioca Chiave d'Argento —\ncome una falena attratta dalla fiamma, ciò che lei attende è un addio che solo tu puoi portare."
  },
  Stage_79574_Name = {
    Text = "Falena del Rogo: Parte IV"
  },
  Stage_79575_Desc = {
    Text = "L'antica luce argentea concede alla ragazza una terza vita.\nLe ultime lacrime cessano di scorrere, e la Sofferenza Eterna ha inizio.\nLa prima nuova lacrima discende, e un Nuovo Capitolo si apre.\nColei che andò incontro alla morte si rimette in cammino, alla ricerca del suo vero sé."
  },
