  Stage_80984_Name = {
    Text = "Prova dello Shaggai Ipnotico"
  },
  Stage_8098_Desc = {
    Text = "Porta la sacra reliquia nella propria carne, guida i fedeli con la dottrina e dissemina la fede attraverso zanne velenose."
  },
  Stage_8098_Name = {
    Text = "Presa della Pietà IV"
  },
  Stage_8099_Desc = {
    Text = [[
Esistevano molto prima che le stelle nascessero.
Sono al contempo illusione e ogni cosa.]]
  },
  Stage_8099_Name = {
    Text = "Residuo Caotico II"
  },
  Stage_8100_Desc = {
    Text = "Custodiscono i segreti dell'oceano in silenzio; le loro anime insondabili come il cosmo."
  },
  Stage_8100_Name = {
    Text = "Residuo abissale IV"
  },
  Stage_8101_Desc = {
    Text = "Si torcono e si fondono nell'oscurità, poi vengono custoditi con cura dentro gli idoli.\nQuesto è un ricongiungimento premeditato."
  },
  Stage_8101_Name = {
    Text = "Viaggio Ultra: Fessura VI"
  },
  Stage_8102_Desc = {
    Text = "Il \"Cancello\" sta per aprirsi, rivelando uno scorcio della verità.\nNon è né bianco né nero — la verità è cromatica eppure torbida."
  },
  Stage_8102_Name = {
    Text = "Eredità di Aequor: Intervallo di Rotazione I"
  },
  Stage_8103_Name = {
    Text = "Prova dell'Apostolo del mare"
  },
  Stage_8104_Desc = {
    Text = "Il Museo delle Cere Rogers si trova all'estremità di Via Southwark, nei pressi di un affluente del Taym.\nDi aspetto dimesso, eppure attira da lontano gli appassionati di arte d'avanguardia."
  },
  Stage_8104_Name = {
    Text = "Museo delle Cere Frenetico III"
  },
  Stage_8105_Desc = {
    Text = "Come può un tramonto durare in eterno?"
  },
  Stage_8105_Name = {Text = "Tramonto"},
  Stage_8106_Desc = {
    Text = "Spine aguzze perforarono l'arco un tempo impeccabile — ciò che emerse dalla fenditura era qualcosa di diverso da \"Cerbero\"."
  },
  Stage_8106_Name = {
    Text = "Carapace Incrinato"
  },
  Stage_8107_Desc = {
    Text = "Cosa accecò i suoi occhi?\nL'amore, la pietà, la giustizia — o un eccesso di gratitudine?"
  },
  Stage_8107_Name = {
    Text = "Trascendenza"
  },
  Stage_8108_Desc = {
    Text = "Vagano come imperscrutabili stregoni attraverso gli interstizi del tempo e dello spazio.\nNessun odio, nessuna paura, nessuna pietà."
  },
  Stage_8108_Name = {
    Text = "Residuo Cosmico IV"
  },
  Stage_8109_Desc = {
    Text = "Il \"Cancello\" sta per aprirsi, rivelando uno scorcio della verità.\nNon è né bianco né nero — la verità è cromatica eppure torbida."
  },
  Stage_8109_Name = {
    Text = "Eredità di Aequor: Intervallo di Rotazione I"
  },
  Stage_8110_Desc = {
    Text = "Seguendo le voci sul Segugio infernale \"Cerbero\", gli investigatori Mythag giungono alla periferia di una piccola città chiamata Rye, nei pressi di Londinium, per svelare il mistero dietro le sparizioni..."
  },
  Stage_8110_Name = {
    Text = "Pensa Prima di Agire"
  },
  Stage_8111_Desc = {
    Text = [[
Buone e cattive notizie. Gli indizi perduti non riappariranno, ma nuovi casi si tramano nell'ombra.
Credici, gli investigatori non torneranno a mani vuote questa volta.]]
  },
  Stage_8111_Name = {
    Text = "Buone Notizie, Cattive Notizie"
  },
  Stage_8112_Desc = {
    Text = "La misteriosa dama del \"narciso\"."
  },
  Stage_8112_Name = {
    Text = "Salve, Lady Daffodil"
  },
  Stage_8113_Desc = {
    Text = "Un tono frenetico; un fetore di sangue — questa è la cerimonia di Benvenuto di Rye."
  },
  Stage_8113_Name = {
    Text = "Benvenuti a Rye"
  },
  Stage_8114_Desc = {
    Text = "Le gambe umane non possono superare l'agilità dei quadrupedi selvatici, ma la mente sì.\nTuttavia, dopo aver catturato il \"Segugio infernale,\" cosa vi attende?"
  },
  Stage_8114_Name = {
    Text = "Asso nella Manica"
  },
  Stage_8115_Desc = {
    Text = "Daffodil ti ha portato la tua \"risposta\". Un nuovo pezzo avanza sulla scacchiera, recando un sogno di vento e neve."
  },
  Stage_8115_Name = {
    Text = "Spina nel Fianco"
  },
  Stage_8116_Desc = {
    Text = "Ti auguro un viaggio piacevole."
  },
  Stage_8116_Name = {
    Text = "Buon Viaggio"
  },
  Stage_8117_Desc = {
    Text = "Nella metropolitana, sei stato attaccato da un misterioso Assassino..."
  },
  Stage_8117_Name = {
    Text = "Una Vita Senza Amici"
  },
