  Stage_8135_Name = {
    Text = "Immersione Fantasmatica I"
  },
  Stage_8137_Desc = {
    Text = "Lei è il confine dove sogno e realtà si intrecciano — il riflesso che dimora nelle profondità di ogni anima che volge lo sguardo al cielo notturno."
  },
  Stage_8137_Name = {
    Text = "Stelle distorte"
  },
  Stage_8138_Desc = {
    Text = "Una massa grezza, non digerita. La gente la chiama escremento — o caos.\nIl mondo nacque dall'escremento."
  },
  Stage_8138_Name = {
    Text = "Ammasso del Caos II"
  },
  Stage_8139_Desc = {
    Text = "Si contorce, trasuda... La massa protoplasmatica scivola attraverso le fessure delle sue catene.\nQuesto è il prezzo che ella paga per la \"libertà.\""
  },
  Stage_8139_Name = {
    Text = "Catena dell'oscurità IV"
  },
  Stage_8140_Desc = {
    Text = "Si torcono e si fondono nell'oscurità, poi vengono custoditi con cura dentro gli idoli.\nQuesto è un ricongiungimento premeditato."
  },
  Stage_8140_Name = {
    Text = "Dominio del Caos: Fessura V"
  },
  Stage_8141_Desc = {
    Text = "Qui giacciono le rovine di un'antica città nel dormiveglia.\nDorme profondamente quanto il suo padrone."
  },
  Stage_8141_Name = {
    Text = "Rovine di Pohnpei III"
  },
  Stage_8142_Desc = {
    Text = "Cosa accecò i suoi occhi?\nL'amore, la pietà, la giustizia — o un eccesso di gratitudine?"
  },
  Stage_8142_Name = {
    Text = "Trascendenza"
  },
  Stage_8143_Desc = {
    Text = "Spine aguzze perforarono l'arco un tempo impeccabile — ciò che emerse dalla fenditura era qualcosa di diverso da \"Cerbero\"."
  },
  Stage_8143_Name = {
    Text = "Carapace Incrinato"
  },
  Stage_8144_Desc = {
    Text = "Come può un tramonto durare in eterno?"
  },
  Stage_8144_Name = {Text = "Tramonto"},
  Stage_8145_Desc = {
    Text = "La \"Mano\" solleva il sipario della notte, giungendo silenziosamente in questo mondo."
  },
  Stage_8145_Name = {
    Text = "Immersione Fantasmatica I"
  },
  Stage_8146_Desc = {
    Text = "Idoli di origine ignota vagano e fremono nell'oscurità.\nSi muovono seguendo ritmi ancestrali, attratti dal suono di un flauto lontano."
  },
  Stage_8146_Name = {
    Text = "Eredità di Aequor: Fessura II"
  },
  Stage_8147_Desc = {
    Text = "Crac—si scinde.\nSnap—si spezza."
  },
  Stage_8147_Name = {
    Text = "Casa delle Bambole"
  },
  Stage_8148_Desc = {
    Text = "Il \"Cancello\" è stato aperto. L'illusione volge al termine.\nSilenzio... Non guardare. Non ascoltare."
  },
  Stage_8148_Name = {
    Text = "Dominio del Caos: Intervallo di Rotazione IV"
  },
  Stage_8149_Desc = {
    Text = "Il \"Cancello\" è stato aperto. L'illusione volge al termine.\nSilenzio... Non guardare. Non ascoltare."
  },
  Stage_8149_Name = {
    Text = "Dominio del Caos: Intervallo di Rotazione IV"
  },
  Stage_8150_Desc = {
    Text = "Il \"Cancello\" è stato aperto. L'illusione volge al termine.\nSilenzio... Non guardare. Non ascoltare."
  },
  Stage_8150_Name = {
    Text = "Dominio del Caos: Intervallo di Rotazione IV"
  },
  Stage_8151_Desc = {
    Text = "Déjà vu e realtà stanno lacerando il Custode in due — una metà rimasta nella Memoria, l'altra metà rimasta nel presente."
  },
  Stage_8151_Name = {Text = "Pugnale"},
  Stage_8152_Desc = {
    Text = "Il porto di notte, i semplici Residenti e la loro calorosa ospitalità."
  },
  Stage_8152_Name = {
    Text = "Imboscata da ogni lato"
  },
  Stage_8153_Desc = {
    Text = "Un inizio banale: un Custode solitario e amnesiaco.\nLa differenza è che questa volta, {Male=si risveglia,Female=si risveglia} sul mare solitario."
  },
  Stage_8153_Name = {
    Text = "Occhio del Ciclone"
  },
  Stage_8154_Desc = {
    Text = "Apostolo dei mari."
  },
  Stage_8154_Name = {Text = "Apostolo"},
  Stage_8155_Desc = {
    Text = "Su una nave, chi altri è degno di fiducia se non il capitano?"
  },
  Stage_8155_Name = {
    Text = "Membro dell'Equipaggio"
  },
  Stage_8156_Desc = {
    Text = "Quando non c'è via d'uscita, un compagno ben addestrato è spesso la chiave per la Rottura — Ramona te lo ha insegnato ancora una volta."
  },
  Stage_8156_Name = {
    Text = "Senza Scampo"
  },
  Stage_8157_Desc = {
    Text = "Attraversando i molti mari — oltre ai nemici, forse vi sarà anche un Bagliore di speranza."
  },
  Stage_8157_Name = {
    Text = "L'Indulgente"
  },
  Stage_8158_Desc = {
    Text = "Era la lama colossale di chi intendeva fendere l'oceano; era l'ambizione di chi intendeva soggiogare tutti i mari."
  },
  Stage_8158_Name = {
    Text = "Il Folle e la Grande Lama"
  },
  Stage_8159_Desc = {
    Text = "Un incubo mai dissolto — una realtà distorta che le fece ombra per tutta la vita."
  },
  Stage_8159_Name = {
    Text = "Realtà Distorta"
  },
  Stage_8160_Desc = {
    Text = "Si torcono e si fondono nell'oscurità, poi vengono custoditi con cura dentro gli idoli.\nQuesto è un ricongiungimento premeditato."
  },
  Stage_8160_Name = {
    Text = "Viaggio Ultra: Fessura V"
  },
  Stage_8161_Desc = {
    Text = "Londinium è di fama rinomata per la sua splendente civiltà industriale e la nebbia plumbea che avvolge la città.\nLa nebbia è onnipresente — per i passanti, poco più di un incidentale, insignificante fastidio."
  },
  Stage_8161_Name = {
    Text = "Città della grande nebbia IV"
  },
  Stage_8162_Desc = {
    Text = "L'orizzonte curvo celato nelle profondità del cosmo.\nTi conduce da un'oscurità a un'altra."
  },
  Stage_8162_Name = {
    Text = "Gola di Schwarzschild IV"
  },
  Stage_8163_Desc = {
    Text = "Il vuoto è la nostra origine. Il vuoto è la nostra fine."
  },
  Stage_8163_Name = {
    Text = "Sussurri dell'immortale"
  },
  Stage_8164_Desc = {
    Text = "Sotto il desolato ponte ferroviario, un Mostro enorme e rigonfio emette strani ringhi. Per raggiungere il Sanatorio di Rye, bisogna prima attraversare questo luogo."
  },
  Stage_8164_Name = {
    Text = "La Corrente ti Guiderà"
  },
  Stage_8165_Desc = {
    Text = [[
Elworth sorge al polo di Kadath, perennemente avvolta da ghiaccio e neve che mai si sciolgono.
Sotto la spessa, implacabile crosta di ghiaccio, il debole pulsare della vita giace celato.]]
  },
  Stage_8165_Name = {
    Text = "Montagne distorte I"
  },
  Stage_8166_Desc = {
    Text = "Idoli di origine ignota vagano e fremono nell'oscurità.\nSi muovono seguendo ritmi ancestrali, attratti dal suono di un flauto lontano."
  },
  Stage_8166_Name = {
    Text = "Dominio del Caos: Fessura VIII"
  },
  Stage_8167_Desc = {
    Text = "\"È l'Uno. È il Tutto. È la speranza che apre il portale della Verità.\"\nInnumerevoli chiavi formarono un cerchio. Cadono dai cieli, portando all'umanità una speranza gravosa.\nE tombe gravose."
  },
  Stage_8167_Name = {
    Text = "Immersione Fantasmatica IV"
  },
  Stage_8168_Desc = {
    Text = "Il \"Cancello\" sta per aprirsi, rivelando uno scorcio della verità.\nNon è né bianco né nero — la verità è cromatica eppure torbida."
  },
  Stage_8168_Name = {
    Text = "Palude di Caro: Fessura III"
  },
  Stage_8169_Desc = {
    Text = "\"È l'Uno. È il Tutto. È la speranza che apre il portale della Verità.\"\nInnumerevoli chiavi formarono un cerchio. Cadono dai cieli, portando all'umanità una speranza gravosa.\nE tombe gravose."
  },
  Stage_8169_Name = {
    Text = "Immersione Fantasmatica VI"
  },
  Stage_8170_Desc = {
    Text = "\"È l'Uno. È il Tutto. È la speranza che apre il portale della Verità.\"\nInnumerevoli chiavi formarono un cerchio. Cadono dai cieli, portando all'umanità una speranza gravosa.\nE tombe gravose."
  },
  Stage_8170_Name = {
    Text = "Immersione Fantasmatica VII"
  },
  Stage_8171_Desc = {
    Text = "\"È l'Uno. È il Tutto. È la speranza che apre il portale della Verità.\"\nInnumerevoli chiavi formarono un cerchio. Cadono dai cieli, portando all'umanità una speranza gravosa.\nE tombe gravose."
  },
  Stage_8171_Name = {
    Text = "Immersione Fantasmatica I"
  },
  Stage_8172_Desc = {
    Text = "\"È l'Uno. È il Tutto. È la speranza che apre il portale della Verità.\"\nInnumerevoli chiavi formarono un cerchio. Cadono dai cieli, portando all'umanità una speranza gravosa.\nE tombe gravose."
  },
  Stage_8172_Name = {
    Text = "Immersione Fantasmatica II"
  },
  Stage_8173_Desc = {
    Text = "Idoli di origine ignota vagano e fremono nell'oscurità.\nSi muovono seguendo ritmi ancestrali, attratti dal suono di un flauto lontano."
  },
  Stage_8173_Name = {
    Text = "Viaggio Ultra: Fessura II"
  },
  Stage_8174_Desc = {
    Text = "Egli non può essere Lui, e Lui non potrà mai essere lui.\nSì... Sì, solo il mio Dio è il vero Lui."
  },
  Stage_8174_Name = {
    Text = "Luce perduta"
  },
  Stage_81757_Desc = {
    Text = "Il radioso Reame Divino apparve gradualmente nei tuoi occhi dischiusi.\nLà, riceverai la promessa e avrai ogni cosa."
  },
  Stage_81757_Name = {
    Text = "Sussurri del Regno Divino"
  },
  Stage_81758_Desc = {
    Text = "Attraverso quella statuetta d'avorio, il Suo sguardo discende sul mondo mortale.\nDa questo istante, sia voi che io siamo sommersi nella Sua volontà."
  },
  Stage_81758_Name = {
    Text = "Sguardo dell'Icona Celeste"
  },
  Stage_81759_Desc = {
    Text = [[
Il cosmo sconfinato converge dentro di voi, come stelle che si precipitano verso l'istante dell'allineamento.
Rispondete a questo Richiamo Dal Nulla. Sua progenie. Suo burattino.]]
  },
  Stage_81759_Name = {
    Text = "Il Richiamo del Vuoto"
  },
  Stage_8175_Desc = {
    Text = "La realtà semina i germi della rovina, mentre il destino guida l'incontro."
  },
  Stage_8175_Name = {
    Text = "Seme del Destino"
  },
  Stage_81760_Desc = {
    Text = "Il varco tra illusione e realtà, il rituale è iniziato.\nGioite, gridate, la vostra gioia e il vostro dolore trascenderanno le dimensioni, divenendo l'inno dell'avvento del Reame Divino."
  },
  Stage_81760_Name = {
    Text = "Echi del Rito"
  },
  Stage_81761_Desc = {
    Text = "Tutta l'estasi è passata.\nTrascini il tuo corpo scisso, estendi i tuoi Tentacoli e lanci uno stridio orrificante e profanatore come primo grido dopo il risveglio.\n\n\"Il suo regno divino giungerà finalmente.\""
  },
  Stage_81761_Name = {
    Text = "Devozione Ingiustificata"
  },
  Stage_81762_Desc = {
    Text = "Ah — ascoltate questa voce del caos, questa fantasmagoria senza fine.\nIl dio ha emanato il Suo decreto divino, e voi, Sua progenie e Suo burattino, lo eseguirete con assoluta fedeltà."
  },
  Stage_81762_Name = {
    Text = "Decreto del Sovrano"
  },
  Stage_81763_Desc = {
    Text = "Il battito accelerato del cuore è solo il precursore del fremito della carne.\nNon lasciatevi prendere dal panico — è soltanto il suono del vostro sangue che si risveglia."
  },
  Stage_81763_Name = {
    Text = "Fremiti dell'Involucro"
  },
  Stage_8176_Desc = {
    Text = "Un secondo cuore batte dentro Murphy — dobbiamo impedire l'imminente \"Rituale di Nascita\"."
  },
  Stage_8176_Name = {
    Text = "Un Altro Miracolo"
  },
  Stage_8177_Desc = {
    Text = "Superare i propri limiti non è mai semplice. Ma questa volta, il Custode ha trovato la stella più luminosa nel firmamento."
  },
  Stage_8177_Name = {
    Text = "Inseguendo le Stelle"
  },
  Stage_81781_Desc = {
    Text = "Quel disastro invisibile risorge, inghiottendo passato e presente di questo mondo materiale nelle profondità dell'abisso."
  },
