  Stage_8178_Desc = {
    Text = "Gli esseri umani plasmano il mondo con la propria volontà, e dal mondo vengono a loro volta plasmati."
  },
  Stage_8178_Name = {
    Text = "Determinazione"
  },
  Stage_81790_Desc = {
    Text = "Il vortice della Marea nera ribolle; presagi funesti pervadono il Dominio mentre l'oscurità profonda si tramuta in una gabbia per i viandanti."
  },
