  Stage_88880_Desc = {
    Text = "Stringo il fuoco che un tempo hai acceso.\nUn tempo mi hai guidato, io sarò i tuoi occhi, conducendoti a rivedere la luce.\nIl sentiero che hai percorso, io avanzerò per te, tutte le recinzioni arrugginite crolleranno dinanzi a questo fuoco."
  },
  Stage_88880_Name = {
    Text = "Portatore di Candela: Parte III"
  },
  Stage_88881_Desc = {
    Text = "Una città congelata nel tempo, che preserva un esemplare di civiltà."
  },
  Stage_88881_Name = {
    Text = "Tassidermia"
  },
  Stage_88882_Desc = {
    Text = "Nacque stolto e ottuso, costretto da una vita semplice, cieco e ostinato.\nMa chi dice che lo stolto non possa forgiare un nuovo sentiero? Ogni prigionia non è che una tempesta ancora chiusa nel guscio; anche se non sa nulla, volerà comunque coraggioso verso il cielo sconosciuto con le sue ali."
  },
  Stage_88882_Name = {
    Text = "Il Folle: Follia"
  },
  Stage_88883_Desc = {
    Text = "Ho sognato i giorni lontani di un tempo.\nAllora tu indicavi il libro, come stelle profonde sparse su un drappo di velluto blu, dicendo che un giorno avremmo scelto una notte limpida per volare accanto alla luna e vedere com'è davvero il cielo."
  },
  Stage_88883_Name = {
    Text = "Sogni di Ieri: Parte VI"
  },
  Stage_88884_Desc = {
    Text = [[
Ha sempre avuto due ombre; ora ne ha persa una.
Cammina solo sotto il cielo notturno silenzioso, cantando la canzone che compose nella sua infanzia.
Uccelli, uccelli, dove siete...
Ombre, ombre, tornate presto a casa...]]
  },
  Stage_88884_Name = {
    Text = "Viaggio della Solitudine: Parte V"
  },
  Stage_88885_Desc = {
    Text = "Stringo il fuoco che un tempo hai acceso.\nUn tempo mi hai guidato, io sarò i tuoi occhi, conducendoti a rivedere la luce.\nIl sentiero che hai percorso, io avanzerò per te, tutte le recinzioni arrugginite crolleranno dinanzi a questo fuoco."
  },
  Stage_88885_Name = {
    Text = "Portatore di Candela: Parte IV"
  },
  Stage_88886_Desc = {
    Text = "Stringo il fuoco che un tempo hai acceso.\nUn tempo mi hai guidato, io sarò i tuoi occhi, conducendoti a rivedere la luce.\nIl sentiero che hai percorso, io avanzerò per te, tutte le recinzioni arrugginite crolleranno dinanzi a questo fuoco."
  },
  Stage_88886_Name = {
    Text = "Portatore di Candela: Parte II"
  },
  Stage_88887_Desc = {
    Text = "Se si nasce in una gabbia, si può essere naturalmente vincolati?\nSe sepolti nel profondo della terra, ci si sforza di rompere il suolo e rinascere."
  },
  Stage_88887_Name = {
    Text = "Catene Infrante: Parte V"
  },
  Stage_88888_Desc = {
    Text = "Se si nasce in una gabbia, si può essere naturalmente vincolati?\nSe sepolti nel profondo della terra, ci si sforza di rompere il suolo e rinascere."
