  Stage_90691_Name = {
    Text = "Chiaro di luna, scheletri e danza"
  },
  Stage_90985_Desc = {
    Text = "Che i codardi tremino al nostro passaggio.\nOgni gloria appartiene a Roma, e splendidi allori incoroneranno la fronte più fiera."
  },
  Stage_90985_Name = {
    Text = "Corona del Campione: Parte V"
  },
  Stage_90986_Desc = {
    Text = "Applausi e fiori, vino e banchetti, oro e tesori—prendeteli tutti! Ridete di gusto, poiché questa è la giusta ricompensa di un guerriero."
  },
  Stage_90986_Name = {
    Text = "Gloria Trionfale: Parte V"
  },
  Stage_90987_Desc = {
    Text = "Che i codardi tremino al nostro passaggio.\nOgni gloria appartiene a Roma, e splendidi allori incoroneranno la fronte più fiera."
  },
  Stage_90987_Name = {
    Text = "Corona del Campione: II"
  },
  Stage_90988_Desc = {
    Text = "Lascia che la preda si rintani nel profondo dell'Ombra... Il naso di un Cacciatore conosce il dolce fetore della paura. Non può nascondersi."
  },
  Stage_90988_Name = {
    Text = "Cacciatore Feroce: Follia"
  },
  Stage_90989_Desc = {
    Text = "Il grido del corno di guerra squarcia l'alba.\nAvanziamo, infranti mai, incrollabili, finché la vittoria non macchi le nostre mani."
  },
  Stage_90989_Name = {
    Text = "Corno dell'Esodo: Parte II"
  },
  Stage_90990_Desc = {
    Text = "Il grido del corno di guerra squarcia l'alba.\nAvanziamo, infranti mai, incrollabili, finché la vittoria non macchi le nostre mani."
  },
  Stage_90990_Name = {
    Text = "Corno dell'Esodo: Parte IV"
  },
  Stage_90991_Desc = {
    Text = "Vecchie ferite possono ancora dolere tra noi, ma di certo possiamo concordare—per ora—di rivolgere le nostre lame contro questa miserabile invenzione dell'era moderna."
  },
  Stage_90991_Name = {
