  },
  Stage_91015_Name = {
    Text = "Cacciatore Feroce: Parte V"
  },
  Stage_91016_Desc = {
    Text = "Applausi e fiori, vino e banchetti, oro e tesori—prendeteli tutti! Ridete di gusto, poiché questa è la giusta ricompensa di un guerriero."
  },
  Stage_91016_Name = {
    Text = "Gloria Trionfale: Follia"
  },
  Stage_91017_Desc = {
    Text = "Applausi e fiori, vino e banchetti, oro e tesori—prendeteli tutti! Ridete di gusto, poiché questa è la giusta ricompensa di un guerriero."
