  Stage_95333_Name = {
    Text = "Nucleo del Patto: V"
  },
  Stage_95334_Desc = {
    Text = "Stringere la loro mano equivale a firmare un contratto con la Morte. Il momento del pagamento è sempre ignoto."
  },
  Stage_95334_Name = {
    Text = "Nucleo del Patto: Follia"
  },
  Stage_95335_Desc = {
    Text = "Ogni cellula del tuo corpo ripete, non può che ripetere un'unica frase: la Luce è qui."
  },
  Stage_95335_Name = {
    Text = "Rogo Divoratore: III"
  },
  Stage_95336_Desc = {
    Text = "Il sole discende sulla terra, un'orrifica ascesa dall'abisso. Ogni cosa si dissolve in tributo alla sua grandezza."
  },
  Stage_95336_Name = {
    Text = "Il Sole sulla Terra: III"
  },
  Stage_95337_Desc = {
    Text = "Quando il sole farà ritorno nell'abisso, il mondo cadrà nel silenzio. Poiché null'altro che cenere rimarrà."
  },
  Stage_95337_Name = {
    Text = "Rovine Silenziose: I"
  },
  Stage_95338_Desc = {
    Text = "Quando il sole farà ritorno nell'abisso, il mondo cadrà nel silenzio. Poiché null'altro che cenere rimarrà."
  },
  Stage_95338_Name = {
